const r = await tools.pwsh({
  description: "查看第二大脑仓库结构",
  command: `
Get-ChildItem "D:\\GitHub\\My-second-brain" | Select-Object Name, Mode, LastWriteTime | Format-Table -AutoSize | Out-String
Write-Host '--- README / 说明文件 ---'
Get-ChildItem "D:\\GitHub\\My-second-brain" -File -Recurse -Depth 1 -ErrorAction SilentlyContinue | Where-Object { $_.Name -match 'readme|README|说明|\.md$' } | Select-Object FullName, Length | Format-Table -AutoSize | Out-String
Write-Host '--- git remote ---'
git -C "D:\\GitHub\\My-second-brain" remote -v
`
});
console.log(r.stdout);
console.error(r.stderr?.text || "");
